}

function quote(text) {
  return `"${text.replaceAll('"', '""')}"`;
}

function formatRecord(values, delimiter, isFirstLine, rowIndex) {
  const delimiterCode = delimiter.charCodeAt(0);
  const texts = new Array(values.length);
  for (let i = 0; i < values.length; i++) {
    const text = valueToText(values[i], rowIndex, i);
    texts[i] = needsQuotes(text, delimiterCode) ? quote(text) : text;
  }
