function stringify(rows, options = {}) {
  checkOptions(options, 'stringify');
  const delimiter = readDelimiter(options.delimiter, 'stringify');
  const eol = readEol(options.eol);
  const header = readHeader(options.header);
  if (!Array.isArray(rows)) {
    throw new TypeError(`stringify: rows must be an array, received ${describe(rows)}`);
  }

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, true, 'header'));
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
