'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv.js');
const { outcome, parseOutcome, makeRandom, randomText } = require('./helpers.js');

function assertCsvError(fn, line, column, messagePattern) {
  assert.throws(fn, (error) => {
    assert.ok(error instanceof CsvError, `expected a CsvError, got ${error}`);
    assert.deepEqual({ line: error.line, column: error.column }, { line, column });
    if (messagePattern) assert.match(error.message, messagePattern);
    return true;
  });
}

describe('parse: argument validation', () => {
  it('throws TypeError when text is not a string', () => {
    for (const text of [undefined, null, 42, true, ['a'], {}, Buffer.from('a'), new String('a')]) {
      assert.throws(() => parse(text), TypeError);
    }
  });

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
    assert.deepEqual(parse('', { header: true, skipEmptyLines: true }), []);
  });

  it('rejects a delimiter that is not one character other than a quote, CR or LF', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', '\r\n', '😀', 1, null, [',']]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
    }
  });

  it('rejects options that are not an object, and non-boolean flags', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { header: 1 }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 'true' }), TypeError);
  });

  it('ignores options it does not know, such as stringify-only ones', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });
});

});

describe('parse: several errors in one input', () => {
  it('throws the error a left-to-right read reaches first', () => {
    // The stray x comes before the record ends, so it wins over the field count.
    assertCsvError(() => parse('a,b\n1,2,"3"x', { header: true }), 2, 8);
    // The count is checked when record 2 ends, before the unclosed quote.
    assertCsvError(() => parse('a,b\n1\n"x', { header: true }), 2, 1);
    // A duplicate is known when its field ends, before the stray y.
    assertCsvError(() => parse('a,a,"b"y', { header: true }), 1, 3);
    // An unclosed quote means the record never ends, so its count is never checked.
    assertCsvError(() => parse('a,b\n1,2,"3', { header: true }), 2, 5);
    assertCsvError(() => parse('"a"x,"b"y'), 1, 4);
  });
});

describe('CsvError', () => {
  it('is an Error subclass with a position in its properties and message', () => {
    const error = outcome(() => parse('ok\n"bad')).error;
    assert.deepEqual(error, { line: 2, column: 1 });
    assert.throws(
      () => parse('ok\n"bad'),
      (thrown) =>
        thrown instanceof Error &&
        thrown instanceof CsvError &&
        thrown.name === 'CsvError' &&
        /line 2, column 1/.test(thrown.message),
    );
  });

  it('can be constructed directly', () => {
    const error = new CsvError('custom', 3, 7);
    assert.equal(error.line, 3);
    assert.equal(error.column, 7);
    assert.match(error.message, /^custom/);
  });
});

// An index-based reading of the spec over the whole string, written
// separately from the tokenizer, used as an oracle for random inputs.
function referenceParse(input, { delimiter = ',', header = false, skipEmptyLines = false } = {}) {
  const text = input.startsWith('﻿') ? input.slice(1) : input;
  const n = text.length;
  const lineAt = [];
  const columnAt = [];
  let line = 1;
  let column = 1;
  for (let i = 0; i <= n; i++) {
    lineAt.push(line);
    columnAt.push(column);
    if (text[i] === '\r' || (text[i] === '\n' && text[i - 1] !== '\r')) {
      line++;
      column = 1;
    } else if (text[i] !== '\n') {
      column++;
    }
  }
  const fail = (index) => {
    throw new CsvError('reference', lineAt[index], columnAt[index]);
  };
  const isBreak = (i) => text[i] === '\r' || text[i] === '\n';
  const afterBreak = (i) => (text[i] === '\r' && text[i + 1] === '\n' ? i + 2 : i + 1);

  const records = [];
  let columns = null;
  const emit = (fields, start) => {
    if (!header) records.push(fields);
    else if (columns === null) columns = fields;
    else if (fields.length !== columns.length) throw new CsvError('reference', lineAt[start], 1);
    else records.push(Object.fromEntries(columns.map((name, k) => [name, fields[k]])));
  };

  let i = 0;
  while (i < n) {
    const start = i;
    if (isBreak(i)) {
      i = afterBreak(i);
      if (!skipEmptyLines) emit([''], start);
      continue;
    }
    const fields = [];
    const seen = header && columns === null ? new Set() : null;
    for (;;) {
      const fieldStart = i;
      let value = '';
      if (text[i] === '"') {
        let j = i + 1;
        for (;;) {
          if (j >= n) fail(fieldStart);
          if (text[j] !== '"') {
            value += text[j++];
          } else if (text[j + 1] === '"') {
            value += '"';
            j += 2;
          } else {
            j++;
            break;
          }
        }
        if (j < n && text[j] !== delimiter && !isBreak(j)) fail(j);
        i = j;
      } else {
        let j = i;
        while (j < n && text[j] !== delimiter && !isBreak(j)) j++;
        value = text.slice(i, j);
        i = j;
      }
      if (seen) {
        if (seen.has(value)) fail(fieldStart);
        seen.add(value);
      }
      fields.push(value);
      if (i < n && text[i] === delimiter) {
        i++;
        continue;
      }
      break;
    }
    if (i < n) i = afterBreak(i);
    emit(fields, start);
  }
  return records;
}

describe('parse: agreement with a reference reading of the spec', () => {
  const alphabet = ['a', 'b', ',', ';', '"', '"', '"', '\r', '\n', ' ', '﻿', '😀'];
  const optionSets = [
    {},
    { skipEmptyLines: true },
    { header: true },
    { header: true, skipEmptyLines: true },
    { delimiter: ';' },
    { delimiter: ';', header: true },
  ];

  for (const options of optionSets) {
    it(`matches on random inputs with ${JSON.stringify(options)}`, () => {
      const random = makeRandom(0xc5f + optionSets.indexOf(options));
      for (let run = 0; run < 3000; run++) {
        const text = randomText(random, alphabet, 14);
        assert.deepEqual(
          parseOutcome(text, options),
          outcome(() => referenceParse(text, options)),
          `input ${JSON.stringify(text)}`,
        );
      }
    });
  }
});
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.end(), []);
  });

  it('strips a BOM only at the start of the whole input', () => {
    const first = createParser();
    first.write('');
    assert.deepEqual(first.write('﻿a\n'), [['a']]);

    const later = createParser();
    later.write('a');
    assert.deepEqual(later.write('﻿b\n'), [['a﻿b']]);
  });
});

describe('createParser: errors and lifecycle', () => {
  it('validates options when it is created', () => {
    assert.throws(() => createParser(null), TypeError);
    assert.throws(() => createParser({ delimiter: '"' }), TypeError);
    assert.throws(() => createParser({ header: 'yes' }), TypeError);
  });

  it('throws TypeError for a chunk that is not a string, then stays closed', () => {
    for (const chunk of [undefined, null, 42, Buffer.from('a'), ['a']]) {
      const parser = createParser();
      assert.throws(() => parser.write(chunk), TypeError);
      assertClosed(parser);
    }
  });

  it('throws on every call after end()', () => {
    const parser = createParser();
    parser.write('a');
    assert.deepEqual(parser.end(), [['a']]);
    assertClosed(parser);
  });

  it('stays closed after write throws a CsvError', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('ok\n'), [['ok']]);
    assert.throws(() => parser.write('"a"x'), { name: 'CsvError', line: 2, column: 4 });
    assertClosed(parser);
  });

  it('reports an unclosed quote from end() and stays closed', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\n"b'), [['a']]);
    assert.throws(() => parser.end(), (error) => error instanceof CsvError && error.line === 2 && error.column === 1);
    assertClosed(parser);
  });

  it('checks the field count in the write that ends the record', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('a,b\n1'), []);
    assert.throws(() => parser.write('\n'), { name: 'CsvError', line: 2, column: 1 });
  });
});

describe('createParser: same result as parse wherever the input is split', () => {
  const corpus = [
    'a,b\r\nc,d\r\n',
    'a\rb\nc\r\n\r\nd',
    '"a""b",c\r\n"x\r\ny",""\n',
    '"""",""""""\r',
    '﻿"h1",h2\n1,2\n',
    'a,"b"c',
    'x\n"never closed\r\n',
    '\n\r\n\r\r\n',
    'id,id\n1,2',
    'a,b\n1,2,3\n',
    '😀,"é\r\n",\n',
  ];
  const optionSets = [{}, { skipEmptyLines: true }, { header: true }, { header: true, skipEmptyLines: true }];

  for (const text of corpus) {
    it(`splits ${JSON.stringify(text)} at every one and two points`, () => {
      for (const options of optionSets) {
        const expected = parseOutcome(text, options);
        const check = (chunks) =>
          assert.deepEqual(streamOutcome(chunks, options), expected, `${JSON.stringify(chunks)} ${JSON.stringify(options)}`);
        check([...text]);
        check(text.split(''));
        for (let a = 0; a <= text.length; a++) {
          for (let b = a; b <= text.length; b++) check(splitAt(text, [a, b]));
        }
      }
    });
  }

  it('matches parse on random inputs split at random points', () => {
    const random = makeRandom(0x5eed);
    const alphabet = ['a', ',', '"', '"', '\r', '\n', ' ', '﻿'];
    for (let run = 0; run < 3000; run++) {
      const options = random.pick(optionSets);
      const text = randomText(random, alphabet, 20);
      const chunks = randomChunks(text, random);
      assert.deepEqual(streamOutcome(chunks, options), parseOutcome(text, options), JSON.stringify(chunks));
    }
  });
});

describe('createParser: cost stays linear in the input', () => {
  // Re-reading earlier input on every write would make these quadratic,
  // which at this size takes far longer than the timeout.
  it('handles one-character chunks of many records', { timeout: 10_000 }, () => {
    const text = 'id,"quoted ""x""\r\nvalue",z\n'.repeat(10_000);
    const parser = createParser();
    let count = 0;
    for (let i = 0; i < text.length; i++) count += parser.write(text[i]).length;
    count += parser.end().length;
    assert.equal(count, 10_000);
  });

  it('handles one field spread over many one-character chunks', { timeout: 10_000 }, () => {
    const parser = createParser();
    parser.write('"');
    for (let i = 0; i < 200_000; i++) parser.write('x');
    parser.write('"');
    const [record] = parser.end();
    assert.equal(record[0].length, 200_000);
  });
});

