'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv.js');
const { outcome, parseOutcome, makeRandom, randomText } = require('./helpers.js');

function assertCsvError(fn, line, column, messagePattern) {
  assert.throws(fn, (error) => {
    assert.ok(error instanceof CsvError, `expected a CsvError, got ${error}`);
    assert.deepEqual({ line: error.line, column: error.column }, { line, column });
    if (messagePattern) assert.match(error.message, messagePattern);
    return true;
  });
}

describe('parse: argument validation', () => {
  it('throws TypeError when text is not a string', () => {
    for (const text of [undefined, null, 42, true, ['a'], {}, Buffer.from('a'), new String('a')]) {
      assert.throws(() => parse(text), TypeError);
    }
  });

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
    assert.deepEqual(parse('', { header: true, skipEmptyLines: true }), []);
  });

  it('rejects a delimiter that is not one character other than a quote, CR or LF', () => {
    for (const delimiter of ['', ';;', '"', '\r', '\n', '\r\n', '😀', 1, null, [',']]) {
      assert.throws(() => parse('a', { delimiter }), TypeError, `delimiter ${JSON.stringify(delimiter)}`);
    }
  });

  it('rejects options that are not an object, and non-boolean flags', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { header: 1 }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 'true' }), TypeError);
  });

  it('ignores options it does not know, such as stringify-only ones', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });
});

describe('parse: records and fields', () => {
  it('splits fields on commas by default', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
  });

  it('uses a custom delimiter and treats commas as ordinary characters', () => {
    assert.deepEqual(parse('a;b,c\n"x;y";z', { delimiter: ';' }), [
      ['a', 'b,c'],
      ['x;y', 'z'],
    ]);
    assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
  });

  it('accepts CRLF, LF and CR record separators mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('treats LF followed by CR as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  });

  it('keeps whitespace exactly', () => {
    assert.deepEqual(parse(' a , b \t\n  '), [[' a ', ' b \t'], ['  ']]);
  });

  it('keeps empty fields, including a trailing one', () => {
    assert.deepEqual(parse('a,,b\n,\na,\n'), [['a', '', 'b'], ['', ''], ['a', '']]);
  });

  it('passes non-ASCII text through unchanged', () => {
    assert.deepEqual(parse('é,日本,😀'), [['é', '日本', '😀']]);
  });
});

describe('parse: byte order mark', () => {
  it('ignores a leading BOM', () => {
    assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
    assert.deepEqual(parse('﻿id\n1', { header: true }), [{ id: '1' }]);
  });

  it('keeps a BOM that is not the first character of the input', () => {
    assert.deepEqual(parse('a,﻿b'), [['a', '﻿b']]);
    assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
  });

  it('counts columns from the first character after the BOM', () => {
    assertCsvError(() => parse('﻿"a'), 1, 1);
    assertCsvError(() => parse('﻿"a"x'), 1, 4);
  });
});

describe('parse: quoted fields', () => {
  it('keeps delimiters and line breaks inside quotes literally', () => {
    assert.deepEqual(parse('"a,b","c\nd","e\r\nf","g\rh"'), [['a,b', 'c\nd', 'e\r\nf', 'g\rh']]);
  });

  it('reads "" inside a quoted field as one quote', () => {
    assert.deepEqual(parse('"a""b",""""'), [['a"b', '"']]);
  });

  it('reads an empty quoted field as an empty string', () => {
    assert.deepEqual(parse('"",x\n""'), [['', 'x'], ['']]);
  });

  it('ends a quoted field at a delimiter, a line break or the end of input', () => {
    assert.deepEqual(parse('"a","b"\r\n"c"\r"d"\n"e"'), [['a', 'b'], ['c'], ['d'], ['e']]);
  });

  it('treats a quote that does not start a field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c"",d"'), [['a"b', 'c""', 'd"']]);
    assert.deepEqual(parse(' "a",b'), [[' "a"', 'b']]);
  });

  it('rejects a character after the closing quote at that character', () => {
    assertCsvError(() => parse('"ab"c'), 1, 5, /line 1, column 5/);
    assertCsvError(() => parse('x,"a" ,b'), 1, 6);
    assertCsvError(() => parse('x\n"a\nb"c'), 3, 3);
  });

  it('reports a quoted field that is never closed at its opening quote', () => {
    assertCsvError(() => parse('a,"bc'), 1, 3, /never closed/);
    assertCsvError(() => parse('a\nb,"c\nd'), 2, 3);
    // The final `""` is an escaped quote, so the field is still open.
    assertCsvError(() => parse('"a""'), 1, 1);
  });

  it('counts a CRLF inside quotes as one line break and LF CR as two', () => {
    assertCsvError(() => parse('"\r\n"x'), 2, 2);
    assertCsvError(() => parse('"\n\r"x'), 3, 2);
  });

  it('counts columns in UTF-16 code units', () => {
    // The emoji is two code units, so the stray x is at column 7.
    assertCsvError(() => parse('😀,"a"x'), 1, 7);
  });
});

describe('parse: empty lines', () => {
  it('does not start a record after a final line break', () => {
    for (const text of ['a\n', 'a\r\n', 'a\r']) assert.deepEqual(parse(text), [['a']]);
  });

  it('turns every other empty line into a record with one empty field', () => {
    assert.deepEqual(parse('a\n\nb'), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\n'), [['a'], ['']]);
    assert.deepEqual(parse('\n'), [['']]);
    assert.deepEqual(parse('\r\n\r\n'), [[''], ['']]);
  });

  it('drops empty lines with skipEmptyLines', () => {
    assert.deepEqual(parse('a\n\n\r\n\rb\n\n', { skipEmptyLines: true }), [['a'], ['b']]);
    assert.deepEqual(parse('\n', { skipEmptyLines: true }), []);
  });

  it('keeps lines that only look empty with skipEmptyLines', () => {
    assert.deepEqual(parse('""\n \n,', { skipEmptyLines: true }), [[''], [' '], ['', '']]);
  });

  it('still counts skipped lines for error positions', () => {
    assertCsvError(() => parse('a\n\n\n"b', { skipEmptyLines: true }), 4, 1);
  });
});

describe('parse: header mode', () => {
  it('returns plain objects keyed by the header', () => {
    assert.deepEqual(parse('name,age\r\nAda,36\r\nAlan,41\r\n', { header: true }), [
      { name: 'Ada', age: '36' },
      { name: 'Alan', age: '41' },
    ]);
  });

  it('returns [] for an input that is only a header', () => {
    for (const text of ['a,b', 'a,b\n', 'a,b\r\n']) assert.deepEqual(parse(text, { header: true }), []);
  });

  it('works with a custom delimiter', () => {
    assert.deepEqual(parse('a;b\n1;2,3', { header: true, delimiter: ';' }), [{ a: '1', b: '2,3' }]);
  });

  it('reports a duplicate name where the second occurrence starts', () => {
    assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5, /Duplicate header name "a"/);
    assertCsvError(() => parse('a,"a"', { header: true }), 1, 3);
    // The second empty name starts after the last delimiter, at the end of input.
    assertCsvError(() => parse('x,,', { header: true }), 1, 4);
    assertCsvError(() => parse('a,"x\ny",a', { header: true }), 2, 4);
  });

  it('allows repeated values in data records', () => {
    assert.deepEqual(parse('a,b\n1,1', { header: true }), [{ a: '1', b: '1' }]);
  });

  it('rejects a record with more or fewer fields than the header at its first line, column 1', () => {
    assertCsvError(() => parse('a,b\n1,2\n1,2,3', { header: true }), 3, 1, /Expected 2 fields .* found 3/);
    assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
    assertCsvError(() => parse('a,b\n"x\ny",1\n2', { header: true }), 4, 1);
    assertCsvError(() => parse('a,b\n"x\ny"', { header: true }), 2, 1);
  });

  it('treats an empty line as a one-field record unless skipEmptyLines is set', () => {
    assertCsvError(() => parse('a,b\n\n1,2', { header: true }), 2, 1);
    assert.deepEqual(parse('a\n\nx', { header: true }), [{ a: '' }, { a: 'x' }]);
    assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
  });

  it('stores a __proto__ column as an own property', () => {
    const [record] = parse('__proto__,x\n1,2', { header: true });
    assert.equal(Object.getPrototypeOf(record), Object.prototype);
    assert.ok(Object.hasOwn(record, '__proto__'));
    assert.deepEqual(Object.entries(record), [
      ['__proto__', '1'],
      ['x', '2'],
    ]);
  });
});

describe('parse: trim', () => {
  const trim = { trim: true };

  it('is off by default', () => {
    assert.deepEqual(parse(' a , b \n'), [[' a ', ' b ']]);
    assert.deepEqual(parse(' a , b \n', { trim: false }), [[' a ', ' b ']]);
    assertCsvError(() => parse('"a" ,b'), 1, 4);
    assertCsvError(() => parse('"a" ,b', { trim: false }), 1, 4);
  });

  it('removes spaces and tabs from both ends of unquoted fields', () => {
    assert.deepEqual(parse(' a \t,\t b c\t\r\n  x  ', trim), [['a', 'b c'], ['x']]);
    assert.deepEqual(parse('a b ,  ,\t\t,', trim), [['a b', '', '', '']]);
  });

  it('removes only spaces and tabs', () => {
    assert.deepEqual(parse(' a ,\fb\v', trim), [[' a ', '\fb\v']]);
  });

  it('allows blanks around a quoted field and keeps its content exactly', () => {
    assert.deepEqual(parse(' \t" a ""b"" "\t ,  "c\r\n d"  \n', trim), [[' a "b" ', 'c\r\n d']]);
    assert.deepEqual(parse('  ""  ,x', trim), [['', 'x']]);
    assert.deepEqual(parse('"a"  ', trim), [['a']]);
    assert.deepEqual(parse('"a"\t\r\n"b" \r"c"', trim), [['a'], ['b'], ['c']]);
  });

  it('treats a field with blanks before its opening quote as quoted', () => {
    assert.deepEqual(parse('  "a,b"', trim), [['a,b']]);
    assertCsvError(() => parse('  "abc', trim), 1, 3, /never closed/);
  });

  it('keeps a quote in the middle of an unquoted field as ordinary', () => {
    assert.deepEqual(parse(' a "b" ', trim), [['a "b"']]);
  });

  it('still rejects other characters after a closing quote', () => {
    assertCsvError(() => parse('"a" x', trim), 1, 5, /closing quote/);
    assertCsvError(() => parse('"a" "b"', trim), 1, 5);
    assertCsvError(() => parse('"a""" x', trim), 1, 7);
  });

  it('does not trim a blank that is the delimiter', () => {
    assert.deepEqual(parse(' a  b ', { trim: true, delimiter: ' ' }), [['', 'a', '', 'b', '']]);
    assert.deepEqual(parse('\ta\t\t b ', { trim: true, delimiter: '\t' }), [['', 'a', '', 'b']]);
    assert.deepEqual(parse('"a"\t "b" ', { trim: true, delimiter: '\t' }), [['a', 'b']]);
  });

  it('works with header mode and duplicate detection', () => {
    assert.deepEqual(parse(' id , name \n 1 , Ada \n', { trim: true, header: true }), [{ id: '1', name: 'Ada' }]);
    assertCsvError(() => parse('a, a ', { trim: true, header: true }), 1, 4, /Duplicate/);
  });

  it('reads a line of only blanks as a record with one empty field, not an empty line', () => {
    assert.deepEqual(parse('a\n \t\nb', { trim: true, skipEmptyLines: true }), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n\nb', { trim: true, skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('counts positions in the untrimmed text', () => {
    assertCsvError(() => parse('a\n  b,  "c"d', trim), 2, 11);
  });

  it('must be a boolean', () => {
    assert.throws(() => parse('a', { trim: 'yes' }), TypeError);
    assert.throws(() => parse('a', { trim: 1 }), TypeError);
  });
});

describe('parse: comment', () => {
  const comment = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\nb'), [['#a'], ['b']]);
  });

  it('skips a line that starts with the comment character, with its line break', () => {
    assert.deepEqual(parse('#one\na\r\n#two\r\nb\r#three\rc', comment), [['a'], ['b'], ['c']]);
    assert.deepEqual(parse('#only', comment), []);
    assert.deepEqual(parse('#only\n', comment), []);
    assert.deepEqual(parse('#\n#\r\n#\r#', comment), []);
  });

  it('is not an empty line and never a record', () => {
    assert.deepEqual(parse('a\n#x\n\nb', comment), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n#x\nb', { comment: '#', skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('is ordinary anywhere but the first character of a line', () => {
    assert.deepEqual(parse('a#,#b#\n#', comment), [['a#', '#b#']]);
    assert.deepEqual(parse(' #a\n"x"\n"#"\n#\nb,#', comment), [[' #a'], ['x'], ['#'], ['b', '#']]);
    assert.deepEqual(parse('a\n"x\n#y"', comment), [['a'], ['x\n#y']]);
  });

  it('is ordinary after leading blanks with trim', () => {
    assert.deepEqual(parse('  #a\n#b\n', { comment: '#', trim: true }), [['#a']]);
  });

  it('applies to the first line after a BOM', () => {
    assert.deepEqual(parse('﻿#a\nb', comment), [['b']]);
  });

  it('skips a CRLF after a comment as one line break', () => {
    assert.deepEqual(parse('#a\r\nb', comment), [['b']]);
  });

  it('skips comments around the header', () => {
    assert.deepEqual(parse('#c\nid\n#c\n1\n', { comment: '#', header: true }), [{ id: '1' }]);
  });

  it('counts comment lines in error positions', () => {
    assertCsvError(() => parse('#a\r\n#b\nx\r#c\n"y', comment), 5, 1);
    assertCsvError(() => parse('#a\n#b\n"x"y', comment), 3, 4);
    assertCsvError(() => parse('#a\nid,n\n#b\n1', { comment: '#', header: true }), 4, 1);
    assertCsvError(() => parse('#a\nid,id', { comment: '#', header: true }), 2, 4);
  });

  it('accepts any other single character, including a space or tab', () => {
    assert.deepEqual(parse(';a\nb', { comment: ';' }), [['b']]);
    assert.deepEqual(parse(' a\nb', { comment: ' ' }), [['b']]);
    assert.deepEqual(parse('\ta\nb', { comment: '\t' }), [['b']]);
    assert.deepEqual(parse('éa\nb', { comment: 'é' }), [['b']]);
  });

  it('rejects anything but one character other than the delimiter, a quote, CR and LF', () => {
    for (const value of ['', '##', '"', '\r', '\n', ',', '\r\n', '\u{1F600}', 35, null, true, ['#']]) {
      assert.throws(() => parse('a', { comment: value }), TypeError, JSON.stringify(value));
    }
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.throws(() => parse('a', { comment: '\t', delimiter: '\t' }), TypeError);
    assert.deepEqual(parse('#a;b', { comment: ',', delimiter: ';' }), [['#a', 'b']]);
  });
});

describe('parse: several errors in one input', () => {
  it('throws the error a left-to-right read reaches first', () => {
    // The stray x comes before the record ends, so it wins over the field count.
    assertCsvError(() => parse('a,b\n1,2,"3"x', { header: true }), 2, 8);
    // The count is checked when record 2 ends, before the unclosed quote.
    assertCsvError(() => parse('a,b\n1\n"x', { header: true }), 2, 1);
    // A duplicate is known when its field ends, before the stray y.
    assertCsvError(() => parse('a,a,"b"y', { header: true }), 1, 3);
    // An unclosed quote means the record never ends, so its count is never checked.
    assertCsvError(() => parse('a,b\n1,2,"3', { header: true }), 2, 5);
    assertCsvError(() => parse('"a"x,"b"y'), 1, 4);
  });
});

describe('CsvError', () => {
  it('is an Error subclass with a position in its properties and message', () => {
    const error = outcome(() => parse('ok\n"bad')).error;
    assert.deepEqual(error, { line: 2, column: 1 });
    assert.throws(
      () => parse('ok\n"bad'),
      (thrown) =>
        thrown instanceof Error &&
        thrown instanceof CsvError &&
        thrown.name === 'CsvError' &&
        /line 2, column 1/.test(thrown.message),
    );
  });

  it('can be constructed directly', () => {
    const error = new CsvError('custom', 3, 7);
    assert.equal(error.line, 3);
    assert.equal(error.column, 7);
    assert.match(error.message, /^custom/);
  });
});

// An index-based reading of the spec over the whole string, written
// separately from the tokenizer, used as an oracle for random inputs.
function referenceParse(input, { delimiter = ',', header = false, skipEmptyLines = false, trim = false, comment } = {}) {
  const text = input.startsWith('﻿') ? input.slice(1) : input;
  const n = text.length;
  const lineAt = [];
  const columnAt = [];
  let line = 1;
  let column = 1;
  for (let i = 0; i <= n; i++) {
    lineAt.push(line);
    columnAt.push(column);
    if (text[i] === '\r' || (text[i] === '\n' && text[i - 1] !== '\r')) {
      line++;
      column = 1;
    } else if (text[i] !== '\n') {
      column++;
    }
  }
  const fail = (index) => {
    throw new CsvError('reference', lineAt[index], columnAt[index]);
  };
  const isBlank = (i) => (text[i] === ' ' || text[i] === '\t') && text[i] !== delimiter;
  const isBreak = (i) => text[i] === '\r' || text[i] === '\n';
  const afterBreak = (i) => (text[i] === '\r' && text[i + 1] === '\n' ? i + 2 : i + 1);

  const records = [];
  let columns = null;
  const emit = (fields, start) => {
    if (!header) records.push(fields);
    else if (columns === null) columns = fields;
    else if (fields.length !== columns.length) throw new CsvError('reference', lineAt[start], 1);
    else records.push(Object.fromEntries(columns.map((name, k) => [name, fields[k]])));
  };

  let i = 0;
  while (i < n) {
    const start = i;
    if (comment !== undefined && text[i] === comment) {
      while (i < n && !isBreak(i)) i++;
      if (i < n) i = afterBreak(i);
      continue;
    }
    if (isBreak(i)) {
      i = afterBreak(i);
      if (!skipEmptyLines) emit([''], start);
      continue;
    }
    const fields = [];
    const seen = header && columns === null ? new Set() : null;
    for (;;) {
      if (trim) while (i < n && isBlank(i)) i++;
      const fieldStart = i;
      let value = '';
      if (text[i] === '"') {
        let j = i + 1;
        for (;;) {
          if (j >= n) fail(fieldStart);
          if (text[j] !== '"') {
            value += text[j++];
          } else if (text[j + 1] === '"') {
            value += '"';
            j += 2;
          } else {
            j++;
            break;
          }
        }
        if (trim) while (j < n && isBlank(j)) j++;
        if (j < n && text[j] !== delimiter && !isBreak(j)) fail(j);
        i = j;
      } else {
        let j = i;
        while (j < n && text[j] !== delimiter && !isBreak(j)) j++;
        value = text.slice(i, j);
        if (trim) value = value.replace(/[ \t]+$/, '');
        i = j;
      }
      if (seen) {
        if (seen.has(value)) fail(fieldStart);
        seen.add(value);
      }
      fields.push(value);
      if (i < n && text[i] === delimiter) {
        i++;
        continue;
      }
      break;
    }
    if (i < n) i = afterBreak(i);
    emit(fields, start);
  }
  return records;
}

describe('parse: agreement with a reference reading of the spec', () => {
  const alphabet = ['a', 'b', ',', ';', '"', '"', '"', '\r', '\n', ' ', '\t', '#', '﻿', '😀'];
  const optionSets = [
    {},
    { skipEmptyLines: true },
    { header: true },
    { header: true, skipEmptyLines: true },
    { delimiter: ';' },
    { delimiter: ';', header: true },
    { trim: true },
    { trim: true, skipEmptyLines: true, header: true },
    { trim: true, delimiter: '\t' },
    { trim: true, delimiter: ' ' },
    { comment: '#' },
    { comment: '#', skipEmptyLines: true, header: true },
    { comment: ' ', trim: true },
    { comment: 'a', trim: true, header: true },
    { comment: '#', trim: true, delimiter: ';' },
  ];

  for (const options of optionSets) {
    it(`matches on random inputs with ${JSON.stringify(options)}`, () => {
      const random = makeRandom(0xc5f + optionSets.indexOf(options));
      for (let run = 0; run < 3000; run++) {
        const text = randomText(random, alphabet, 14);
        assert.deepEqual(
          parseOutcome(text, options),
          outcome(() => referenceParse(text, options)),
          `input ${JSON.stringify(text)}`,
        );
      }
    });
  }
});
